  public.duplicate_dm_content(uuid, uuid, boolean), public.delete_dm_content(uuid), public.get_dm_content(uuid), public.preview_dm_content(uuid),
  public.get_dm_content_library(uuid, text, boolean), public.get_content_public_info(uuid), public.dm_assign_content(uuid, uuid[], text, jsonb),
  public._dm_add_item(uuid, text, int, text, boolean, uuid), public.apply_character_condition(uuid, uuid, text, boolean, timestamptz, text),
  public._dm_set_catalog_archived(text, text, boolean, text), public._dm_event(uuid, uuid, text, jsonb), public._dm_content_json(uuid),
  public._dm_usage(uuid), public._dm_try(uuid), public._dm_catalog_json(text, text), public._dm_materialize(uuid), public._dm_short(uuid),
  public._dm_can_manage(uuid);
