drop policy "creatures_read" on public.creatures;
create policy "creatures_read" on public.creatures for select to anon, authenticated using (true);
drop policy "class_spell_list_entries_read" on public.class_spell_list_entries;
create policy "class_spell_list_entries_read" on public.class_spell_list_entries for select to anon, authenticated using (true);
do $$
declare t text;
begin
  foreach t in array array['backgrounds', 'background_versions', 'lineages', 'lineage_versions', 'background_ability_options', 'background_feat_grants',
                           'background_proficiency_grants', 'background_features', 'background_equipment_packages', 'background_equipment_entries',
                           'lineage_traits', 'lineage_choices', 'lineage_trait_effects'] loop
    execute format('drop policy "%1$s_read" on public.%1$I', t);
    execute format('create policy "%1$s_read" on public.%1$I for select to anon, authenticated using (true)', t);
  end loop;
end $$;
